CREATE TABLE IF NOT EXISTS "session_pending_messages" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "session_id" varchar NOT NULL, "delivery_mode" varchar NOT NULL, "content" varchar NOT NULL, "attachments_json" varchar NOT NULL, "hidden_context_xml" varchar, "created_at" varchar NOT NULL, FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") );
CREATE INDEX idx_session_pending_messages_session_created ON session_pending_messages(session_id, created_at);
CREATE TABLE IF NOT EXISTS "session_pending_ask_user" ( "request_id" varchar NOT NULL PRIMARY KEY, "session_id" varchar NOT NULL, "questions_json" varchar NOT NULL, "created_at" varchar NOT NULL, FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") );
CREATE INDEX idx_session_pending_ask_user_session ON session_pending_ask_user(session_id);
CREATE TABLE IF NOT EXISTS "messages" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "session_id" varchar NOT NULL, "role" varchar NOT NULL, "content" varchar NOT NULL, "timestamp" varchar, "tool_call_id" varchar, "provider_id" varchar, "prompt_tokens" integer, "completion_tokens" integer, "total_tokens" integer, "cache_read_tokens" integer, "cache_write_tokens" integer, "context_window" integer, "elapsed_ms" bigint, attachments TEXT, reasoning TEXT, tool_calls TEXT, FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") );
CREATE TABLE IF NOT EXISTS "session_runtimes" ( "session_id" varchar NOT NULL PRIMARY KEY, "state" varchar NOT NULL, "browser_takeover_active" boolean NOT NULL, "browser_takeover_alert_pending" boolean NOT NULL, "terminal_task_id" varchar, "terminal_output_file" varchar, "terminal_output_preview" varchar, "terminal_input_notice" varchar, "updated_at" varchar NOT NULL, terminal_background_reason TEXT, run_id TEXT, FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") );
CREATE TABLE IF NOT EXISTS "session_plans" ( "session_id" varchar NOT NULL PRIMARY KEY, "plan_state" varchar NOT NULL, "updated_at" varchar NOT NULL, FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") );
CREATE TABLE IF NOT EXISTS "session_pending_permissions" ( "request_id" varchar NOT NULL PRIMARY KEY, "session_id" varchar NOT NULL, "mode" varchar NOT NULL, "script" varchar NOT NULL, "created_at" varchar NOT NULL, agent_id TEXT, FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") );
CREATE TABLE IF NOT EXISTS "session_pending_workspace" ( "request_id" varchar NOT NULL PRIMARY KEY, "session_id" varchar NOT NULL, "path" varchar NOT NULL, "reason" varchar NOT NULL, "created_at" varchar NOT NULL, FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") );
